import{_ as a,o as r,c as d,a2 as o}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"اینکر ہارڈویئر اور بنیادی ڈھانچہ","description":"","frontmatter":{},"headers":[],"relativePath":"ur/67-锚点硬件与基础设施.md","filePath":"ur/67-锚点硬件与基础设施.md","lastUpdated":1789183869000}'),l={name:"ur/67-锚点硬件与基础设施.md"};function e(i,t,n,s,h,_){return r(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="اینکر-ہارڈویئر-اور-بنیادی-ڈھانچہ" tabindex="-1">اینکر ہارڈویئر اور بنیادی ڈھانچہ <a class="header-anchor" href="#اینکر-ہارڈویئر-اور-بنیادی-ڈھانچہ" aria-label="Permalink to &quot;اینکر ہارڈویئر اور بنیادی ڈھانچہ&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>67</td></tr><tr><td>ماڈیول</td><td>ٹیکنالوجی اور توانائی کا نظام</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>اینکر ہارڈویئر، بنیادی ڈھانچہ، مرکزی اینکر، ثانوی اینکر، توانائی کی تقسیم</td></tr></tbody></table><h2 id="_1-اینکر-ہارڈویئر-کی-تعریف-اور-حیثیت" tabindex="-1">1. اینکر ہارڈویئر کی تعریف اور حیثیت <a class="header-anchor" href="#_1-اینکر-ہارڈویئر-کی-تعریف-اور-حیثیت" aria-label="Permalink to &quot;1. اینکر ہارڈویئر کی تعریف اور حیثیت&quot;">​</a></h2><p>اینکر ہارڈویئر اینکر طریقہ کار کا مادی ذریعہ ہے، یہ قانون کے نیٹ ورک سے بنیادی توانائی اور معلومات کو مادی طیارے تک پہنچانے والا جسمانی انٹرفیس ہے۔ اگر کہا جائے کہ اینکر خود ایک قانون کی سطح کا تصور ہے، تو اینکر ہارڈویئر اس تصور کا انجینئرنگ میں نفاذ ہے — یہ ایک نفیس قانون کی انجینئرنگ کا سامان ہے، جو مخصوص جگہ پر مستحکم اینکر کنکشن قائم کر سکتا ہے، اور اینکر کے ذریعے منتقل ہونے والی توانائی اور معلومات کی تقسیم، کنٹرول اور تاثرات کر سکتا ہے۔</p><p>اینکر ہارڈویئر اور بنیادی ڈھانچہ اینکر سمبیوٹک تہذیب کی سب سے اہم مادی بنیاد ہے۔ اینکر ہارڈویئر کے بغیر، تین سو سادگی کے نظاموں کے کھلنے میں توانائی کی فراہمی کی کمی ہوگی، مشترکہ پیداوار کے معاہدے کے طریقہ کار میں وسائل کی شیڈولنگ کے ذرائع کی کمی ہوگی، اور طیاروں کے درمیان مواصلات اور سمبیوٹک نیٹ ورک میں جسمانی رابطے کی کمی ہوگی۔ اینکر ہارڈویئر کی کوریج کی حد اور چلانے کا معیار براہ راست سمبیوٹک تہذیب کے ارتقاء کی کارکردگی کا تعین کرتا ہے۔</p><h2 id="_2-اینکر-ہارڈویئر-کے-درجہ-بندی-کا-نظام" tabindex="-1">2. اینکر ہارڈویئر کے درجہ بندی کا نظام <a class="header-anchor" href="#_2-اینکر-ہارڈویئر-کے-درجہ-بندی-کا-نظام" aria-label="Permalink to &quot;2. اینکر ہارڈویئر کے درجہ بندی کا نظام&quot;">​</a></h2><p>اینکر ہارڈویئر کو فنکشن اور پیمانے کے مطابق چار درجات میں تقسیم کیا گیا ہے:</p><table tabindex="0"><thead><tr><th>درجہ</th><th>نام</th><th>تعیناتی کی تعداد</th><th>بنیادی فنکشن</th><th>توانائی کا پیمانہ</th></tr></thead><tbody><tr><td>پہلا درجہ</td><td>کائناتی مرکزی اینکر</td><td>1 یونٹ</td><td>پوری کائنات کے اینکر نیٹ ورک کا مرکزی مرکز، بنیادی توانائی کا کل داخلی راستہ</td><td>گیگا اینکر توانائی کی سطح</td></tr><tr><td>دوسرا درجہ</td><td>طیارہ مرکزی اینکر</td><td>ہر اہم طیارے میں 1 یونٹ</td><td>طیارہ کی سطح کی توانائی کی شیڈولنگ اور مواصلات کا بیک بون نوڈ</td><td>میگا اینکر توانائی کی سطح</td></tr><tr><td>تیسرا درجہ</td><td>علاقائی اینکر</td><td>ہر براعظم/ستاروں کے علاقے میں کئی</td><td>علاقائی سطح کی توانائی کی تقسیم اور مواصلاتی رسائی</td><td>کلو اینکر توانائی کی سطح</td></tr><tr><td>چوتھا درجہ</td><td>کمیونٹی اینکر</td><td>شہر/کمیونٹی کی سطح</td><td>آخری توانائی کی فراہمی اور ذاتی سادگی کی معاونت</td><td>اینکر توانائی کی سطح</td></tr></tbody></table><p>چار درجات کے اینکر ہارڈویئر کائناتی مرکز سے ہر کمیونٹی تک ایک مکمل کوریج نیٹ ورک تشکیل دیتے ہیں۔ اعلیٰ درجے کے اینکر نچلے درجے کے اینکرز کو توانائی اور معلومات تقسیم کرتے ہیں، اور نچلے درجے کے اینکرز اعلیٰ درجے کے اینکرز کو سادگی کے تاثرات اور چلانے کی حالت واپس بھیجتے ہیں، &quot;نیچے پھیلنا اور اوپر جمع ہونا&quot; والی توانائی اور معلومات کے بہاؤ کا ڈھانچہ تشکیل دیتے ہیں۔</p><h2 id="_3-اینکر-ہارڈویئر-کے-بنیادی-اجزاء" tabindex="-1">3. اینکر ہارڈویئر کے بنیادی اجزاء <a class="header-anchor" href="#_3-اینکر-ہارڈویئر-کے-بنیادی-اجزاء" aria-label="Permalink to &quot;3. اینکر ہارڈویئر کے بنیادی اجزاء&quot;">​</a></h2><p>ہر اینکر ہارڈویئر (درجے سے قطع نظر) میں درج ذیل بنیادی اجزاء شامل ہوتے ہیں:</p><ol><li><strong>قانون کی گونج کا مرکز</strong>: اینکر ہارڈویئر کا دل، اعلیٰ پاکیزگی والے قانون کے کرسٹل سے بنا، قانون کے نیٹ ورک کے ساتھ مستحکم گونج کا رابطہ قائم کرنے کا ذمہ دار۔ قانون کی گونج کے مرکز کی تیاری میں خلائی قانون کی ٹیکنالوجی اور توانائی کی معیاری کاری کی ٹیکنالوجی کے تعاون کی ضرورت ہوتی ہے، یہ اینکر ہارڈویئر میں سب سے زیادہ ٹیکنالوجی والا جزو ہے</li><li><strong>توانائی کی تقسیم کی صف</strong>: اینکر کے ذریعے منتقل ہونے والی بنیادی توانائی کو پہلے سے طے شدہ تناسب کے مطابق مختلف آؤٹ پٹ چینلز میں تقسیم کرنے کا ذمہ دار۔ توانائی کی تقسیم کی صف کی درستگی براہ راست مشترکہ پیداوار کے معاہدے کے طریقہ کار میں وسائل کی تقسیم کے انصاف کو متاثر کرتی ہے</li><li><strong>معلومات پروسیسنگ ماڈیول</strong>: اندرونی ضرب پھل کے تخمینہ انجن کا سادہ ورژن، اینکر نیٹ ورک میں معلومات کے بہاؤ کو پروسیس کرنے کا ذمہ دار، بشمول سادگی کے تاثرات، مواصلاتی روٹنگ، حالت کی نگرانی وغیرہ</li><li><strong>سمبیوٹک تاثرات کا انٹرفیس</strong>: سمبیوٹک تاثرات کے چکر کے نظام سے منسلک خصوصی انٹرفیس، اس علاقے کے تمام سادگی کرنے والوں اور جانداروں کے ارتقاء کے ڈیٹا اکٹھا کرکے اینکر نیٹ ورک کو واپس بھیجنے کا ذمہ دار</li><li><strong>سلامتی تحفظ کا نظام</strong>: قانون کی رکاوٹ، دراندازی کا پتہ لگانا، ہنگامی کٹائی وغیرہ سمیت متعدد سلامتی میکانزم شامل ہیں، اس بات کو یقینی بناتے ہیں کہ اینکر ہارڈویئر لوٹ ماروں کے ذریعے استعمال یا قانون کی آلودگی کا شکار نہ ہو</li></ol><h2 id="_4-بنیادی-ڈھانچے-کے-معاون-نظام" tabindex="-1">4. بنیادی ڈھانچے کے معاون نظام <a class="header-anchor" href="#_4-بنیادی-ڈھانچے-کے-معاون-نظام" aria-label="Permalink to &quot;4. بنیادی ڈھانچے کے معاون نظام&quot;">​</a></h2><p>اینکر ہارڈویئر کے چلانے کے لیے ایک مکمل معاون بنیادی ڈھانچے کی حمایت درکار ہوتی ہے:</p><ul><li><strong>توانائی کی فراہمی کی سہولیات</strong>: اینکر ہارڈویئر کو مسلسل بنیادی توانائی کی فراہمی فراہم کرتی ہیں، بشمول توانائی اکٹھا کرنے والے اسٹیشن، توانائی ذخیرہ کرنے والی صفیں، توانائی کی منتقلی کے پائپ نیٹ ورک وغیرہ</li><li><strong>خلائی قانون کی سہولیات</strong>: اینکر ہارڈویئر کو خلائی استحکام اور تنہائی کی معاونت فراہم کرتی ہیں، بشمول خلائی اینکرنگ ڈیوائسز، تنہا خلا کی دیکھ بھال کا نظام، خلائی اسامانیتاوں کی نگرانی کے اسٹیشن وغیرہ</li><li><strong>مواصلاتی بنیادی ڈھانچہ</strong>: طیاروں کے درمیان مواصلاتی بیس اسٹیشن، طیارہ اندرونی مواصلاتی نیٹ ورک، ڈیٹا اسٹوریج اور پروسیسنگ سینٹر وغیرہ شامل ہیں</li><li><strong>دیکھ بھال اور یقین دہانی کی سہولیات</strong>: اینکر ہارڈویئر کی دیکھ بھال کے اسٹیشن، پرزہ گودام، تکنیکی اہلکاروں کی تربیت کا مرکز، ہنگامی مرمت کی ٹیمیں وغیرہ شامل ہیں</li><li><strong>معیاری انٹرفیس کی سہولیات</strong>: مختلف درجات، مختلف مینوفیکچررز کے اینکر ہارڈویئر اور معاون آلات کے درمیان باہمی تعامل کو یقینی بنانے والے انٹرفیس کے معیارات اور جانچ کی سہولیات</li></ul><h2 id="_5-اینکر-ہارڈویئر-کی-تعمیر-اور-چلانا" tabindex="-1">5. اینکر ہارڈویئر کی تعمیر اور چلانا <a class="header-anchor" href="#_5-اینکر-ہارڈویئر-کی-تعمیر-اور-چلانا" aria-label="Permalink to &quot;5. اینکر ہارڈویئر کی تعمیر اور چلانا&quot;">​</a></h2><p>اینکر ہارڈویئر کی تعمیر &quot;متحدہ منصوبہ بندی، درجہ بندی کی تعمیر، کھلی اشتراک&quot; کے اصول پر عمل کرتی ہے:</p><ol><li><strong>متحدہ منصوبہ بندی</strong>: پوری کائنات کے اینکر ہارڈویئر کی ترتیب کو سمبیوٹک گورننس ادارے کے ذریعے متحدہ طور پر منصوبہ بندی کیا جاتا ہے، اس بات کو یقینی بناتے ہوئے کہ کوریج یکساں ہے، دہرائی گئی تعمیر اور کوریج کے اندھے علاقوں سے بچا جاتا ہے</li><li><strong>درجہ بندی کی تعمیر</strong>: پہلے اور دوسرے درجے کے اینکرز کو براہ راست تہذیب کی سطح کے اداروں کے ذریعے تعمیر اور چلایا جاتا ہے، تیسرے اور چوتھے درجے کے اینکرز میں طیارہ کی حکومت، کمیونٹی تنظیمیں یا قابل کاروباری ادارے تعمیر میں حصہ لے سکتے ہیں، لیکن انہیں متحدہ تکنیکی معیارات اور آپریشن کے ضوابط کی پابندی کرنی ہوگی</li><li><strong>کھلی اشتراک</strong>: اینکر ہارڈویئر کی بنیادی خدمات (توانائی کی فراہمی، مواصلاتی رسائی، سادگی کی معاونت) تمام جانداروں کے لیے مفت کھلی ہیں، اعلیٰ درجے کی خدمات توانائی کی لاگت کے مطابق معقول فیس وصول کرتی ہیں</li><li><strong>ایک جیسے رکھنے والے مخالف ریگولیشن</strong>: ایک جیسے رکھنے والے مخالف قانون میں واضح طور پر کسی بھی تنظیم یا فرد کو اینکر ہارڈویئر کی تعمیر اور چلانے کے حق پر قبضہ کرنے سے منع کیا گیا ہے، اس بات کو یقینی بناتے ہوئے کہ اینکر بنیادی ڈھانچے کی عوامی نوعیت برقرار رہے</li></ol><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>اینکر ہارڈویئر اور بنیادی ڈھانچہ اینکر سمبیوٹک تہذیب کے &quot;ہڈیوں اور خون کی نالیوں&quot; کے برابر ہیں۔ یہ تجریدی اینکر طریقہ کار کو چھونے، تعمیر کرنے اور دیکھ بھال کرنے کے قابل مادی انجینئرنگ میں تبدیل کرتا ہے، جس سے سمبیوٹک ارتقاء کے تصور کو مضبوط مادی بنیاد ملتی ہے۔ چار درجات کے اینکر نیٹ ورک کی مکمل کوریج کے ساتھ ساتھ، ہینگیوانزھو کائناتی مرکز سے ہر جاندار فرد تک ایک مکمل توانائی اور معلومات کے چکر کا نظام تشکیل دے رہا ہے، جو تہذیب کی جہت کی بلندی کے لیے بنیادی مادی ضمانت ہے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>20-اینکر کا ڈھانچہ اور درجہ بندی</li><li>65-توانائی کی معیاری کاری اور پیمائش</li><li>66-طیاروں کے درمیان مواصلاتی ٹیکنالوجی</li></ul>',22)])])}const g=a(l,[["render",e]]);export{c as __pageData,g as default};
